mkitem!{mkenum!{# [derive (Copy , Clone , Debug , HashStable , TyEncodable , TyDecodable)] pub enum LayoutError < 'tcx > { # [doc = " A type doesn't have a sensible layout."] # [doc = ""] # [doc = " This variant is used for layout errors that don't necessarily cause"] # [doc = " compile errors."] # [doc = ""] # [doc = " For example, this can happen if a struct contains an unsized type in a"] # [doc = " non-tail field, but has an unsatisfiable bound like `str: Sized`."] Unknown (Ty < 'tcx >) , # [doc = " The size of a type exceeds [`TargetDataLayout::obj_size_bound`]."] SizeOverflow (Ty < 'tcx >) , # [doc = " The layout can vary due to a generic parameter."] # [doc = ""] # [doc = " Unlike `Unknown`, this variant is a \"soft\" error and indicates that the layout"] # [doc = " may become computable after further instantiating the generic parameter(s)."] TooGeneric (Ty < 'tcx >) , # [doc = " An alias failed to normalize."] # [doc = ""] # [doc = " This variant is necessary, because, due to trait solver incompleteness, it is"] # [doc = " possible than an alias that was rigid during analysis fails to normalize after"] # [doc = " revealing opaque types."] # [doc = ""] # [doc = " See `tests/ui/layout/normalization-failure.rs` for an example."] NormalizationFailure (Ty < 'tcx > , NormalizationError < 'tcx >) , # [doc = " A non-layout error is reported elsewhere."] ReferencesError (ErrorGuaranteed) , # [doc = " A type has cyclic layout, i.e. the type contains itself without indirection."] Cycle (ErrorGuaranteed) , }}}
