mkitem!{mkenum!{# [doc = " Type size \"skeleton\", i.e., the only information determining a type's size."] # [doc = " While this is conservative, (aside from constant sizes, only pointers,"] # [doc = " newtypes thereof and null pointer optimized enums are allowed), it is"] # [doc = " enough to statically check common use cases of transmute."] # [derive (Copy , Clone , Debug)] pub enum SizeSkeleton < 'tcx > { # [doc = " Any statically computable Layout."] # [doc = " Alignment can be `None` if unknown."] Known (Size , Option < Align >) , # [doc = " This is a generic const expression (i.e. N * 2), which may contain some parameters."] # [doc = " It must be of type usize, and represents the size of a type in bytes."] # [doc = " It is not required to be evaluatable to a concrete value, but can be used to check"] # [doc = " that another SizeSkeleton is of equal size."] Generic (ty :: Const < 'tcx >) , # [doc = " A potentially-wide pointer."] Pointer { # [doc = " If true, this pointer is never null."] non_zero : bool , # [doc = " The type which determines the unsized metadata, if any,"] # [doc = " of this pointer. Either a type parameter or a projection"] # [doc = " depending on one, with regions erased."] tail : Ty < 'tcx > , } , }}}
