mkitem!{mktrait!{# [doc = " Trait for contexts that want to be able to compute layouts of types."] # [doc = " This automatically gives access to `LayoutOf`, through a blanket `impl`."] pub trait LayoutOfHelpers < 'tcx > : HasDataLayout + HasTyCtxt < 'tcx > + HasTypingEnv < 'tcx > { # [doc = " The `TyAndLayout`-wrapping type (or `TyAndLayout` itself), which will be"] # [doc = " returned from `layout_of` (see also `handle_layout_err`)."] type LayoutOfResult : MaybeResult < TyAndLayout < 'tcx > > = TyAndLayout < 'tcx > ; # [doc = " `Span` to use for `tcx.at(span)`, from `layout_of`."] # [inline] fn layout_tcx_at_span (& self) -> Span { DUMMY_SP } # [doc = " Helper used for `layout_of`, to adapt `tcx.layout_of(...)` into a"] # [doc = " `Self::LayoutOfResult` (which does not need to be a `Result<...>`)."] # [doc = ""] # [doc = " Most `impl`s, which propagate `LayoutError`s, should simply return `err`,"] # [doc = " but this hook allows e.g. codegen to return only `TyAndLayout` from its"] # [doc = " `cx.layout_of(...)`, without any `Result<...>` around it to deal with"] # [doc = " (and any `LayoutError`s are turned into fatal errors or ICEs)."] fn handle_layout_err (& self , err : LayoutError < 'tcx > , span : Span , ty : Ty < 'tcx > ,) -> < Self :: LayoutOfResult as MaybeResult < TyAndLayout < 'tcx > > > :: Error ; }}}
mkitem!{mktrait!{# [doc = " Blanket extension trait for contexts that can compute layouts of types."] pub trait LayoutOf < 'tcx > : LayoutOfHelpers < 'tcx > { # [doc = " Computes the layout of a type. Note that this implicitly"] # [doc = " executes in `TypingMode::PostAnalysis`, and will normalize the input type."] # [inline] fn layout_of (& self , ty : Ty < 'tcx >) -> Self :: LayoutOfResult { self . spanned_layout_of (ty , DUMMY_SP) } # [doc = " Computes the layout of a type, at `span`. Note that this implicitly"] # [doc = " executes in `TypingMode::PostAnalysis`, and will normalize the input type."] # [inline] fn spanned_layout_of (& self , ty : Ty < 'tcx > , span : Span) -> Self :: LayoutOfResult { let span = if ! span . is_dummy () { span } else { self . layout_tcx_at_span () } ; let tcx = self . tcx () . at (span) ; MaybeResult :: from (tcx . layout_of (self . typing_env () . as_query_input (ty)) . map_err (| err | self . handle_layout_err (* err , span , ty)) ,) } }}}
