macro_rules! fn_can_unwind_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function fn_can_unwind in module {}", module_path!());
    };
}

mkfn!{
    fn_can_unwind_introspect!();
    # [doc = " Calculates whether a function's ABI can unwind or not."] # [doc = ""] # [doc = " This takes two primary parameters:"] # [doc = ""] # [doc = " * `fn_def_id` - the `DefId` of the function. If this is provided then we can"] # [doc = "   determine more precisely if the function can unwind. If this is not provided"] # [doc = "   then we will only infer whether the function can unwind or not based on the"] # [doc = "   ABI of the function. For example, a function marked with `#[rustc_nounwind]`"] # [doc = "   is known to not unwind even if it's using Rust ABI."] # [doc = ""] # [doc = " * `abi` - this is the ABI that the function is defined with. This is the"] # [doc = "   primary factor for determining whether a function can unwind or not."] # [doc = ""] # [doc = " Note that in this case unwinding is not necessarily panicking in Rust. Rust"] # [doc = " panics are implemented with unwinds on most platform (when"] # [doc = " `-Cpanic=unwind`), but this also accounts for `-Cpanic=abort` build modes."] # [doc = " Notably unwinding is disallowed for more non-Rust ABIs unless it's"] # [doc = " specifically in the name (e.g. `\"C-unwind\"`). Unwinding within each ABI is"] # [doc = " defined for each ABI individually, but it always corresponds to some form of"] # [doc = " stack-based unwinding (the exact mechanism of which varies"] # [doc = " platform-by-platform)."] # [doc = ""] # [doc = " Rust functions are classified whether or not they can unwind based on the"] # [doc = " active \"panic strategy\". In other words Rust functions are considered to"] # [doc = " unwind in `-Cpanic=unwind` mode and cannot unwind in `-Cpanic=abort` mode."] # [doc = " Note that Rust supports intermingling panic=abort and panic=unwind code, but"] # [doc = " only if the final panic mode is panic=abort. In this scenario any code"] # [doc = " previously compiled assuming that a function can unwind is still correct, it"] # [doc = " just never happens to actually unwind at runtime."] # [doc = ""] # [doc = " This function's answer to whether or not a function can unwind is quite"] # [doc = " impactful throughout the compiler. This affects things like:"] # [doc = ""] # [doc = " * Calling a function which can't unwind means codegen simply ignores any"] # [doc = "   associated unwinding cleanup."] # [doc = " * Calling a function which can unwind from a function which can't unwind"] # [doc = "   causes the `abort_unwinding_calls` MIR pass to insert a landing pad that"] # [doc = "   aborts the process."] # [doc = " * This affects whether functions have the LLVM `nounwind` attribute, which"] # [doc = "   affects various optimizations and codegen."] # [inline] # [tracing :: instrument (level = "debug" , skip (tcx))] pub fn fn_can_unwind (tcx : TyCtxt < '_ > , fn_def_id : Option < DefId > , abi : ExternAbi) -> bool { if let Some (did) = fn_def_id { if tcx . codegen_fn_attrs (did) . flags . contains (CodegenFnAttrFlags :: NEVER_UNWIND) { return false ; } if tcx . sess . panic_strategy () == PanicStrategy :: Abort && ! tcx . is_foreign_item (did) { return false ; } if tcx . sess . opts . unstable_opts . panic_in_drop == PanicStrategy :: Abort && tcx . is_lang_item (did , LangItem :: DropInPlace) { return false ; } } use ExternAbi :: * ; match abi { C { unwind } | System { unwind } | Cdecl { unwind } | Stdcall { unwind } | Fastcall { unwind } | Vectorcall { unwind } | Thiscall { unwind } | Aapcs { unwind } | Win64 { unwind } | SysV64 { unwind } => unwind , PtxKernel | Msp430Interrupt | X86Interrupt | GpuKernel | EfiApi | AvrInterrupt | AvrNonBlockingInterrupt | CmseNonSecureCall | CmseNonSecureEntry | Custom | RiscvInterruptM | RiscvInterruptS | RustInvalid | Unadjusted => false , Rust | RustCall | RustCold => tcx . sess . panic_strategy () == PanicStrategy :: Unwind , } }
}
