mkitem!{mktrait!{# [doc = " Trait for contexts that want to be able to compute `FnAbi`s."] # [doc = " This automatically gives access to `FnAbiOf`, through a blanket `impl`."] pub trait FnAbiOfHelpers < 'tcx > : LayoutOfHelpers < 'tcx > { # [doc = " The `&FnAbi`-wrapping type (or `&FnAbi` itself), which will be"] # [doc = " returned from `fn_abi_of_*` (see also `handle_fn_abi_err`)."] type FnAbiOfResult : MaybeResult < & 'tcx FnAbi < 'tcx , Ty < 'tcx > > > = & 'tcx FnAbi < 'tcx , Ty < 'tcx > > ; # [doc = " Helper used for `fn_abi_of_*`, to adapt `tcx.fn_abi_of_*(...)` into a"] # [doc = " `Self::FnAbiOfResult` (which does not need to be a `Result<...>`)."] # [doc = ""] # [doc = " Most `impl`s, which propagate `FnAbiError`s, should simply return `err`,"] # [doc = " but this hook allows e.g. codegen to return only `&FnAbi` from its"] # [doc = " `cx.fn_abi_of_*(...)`, without any `Result<...>` around it to deal with"] # [doc = " (and any `FnAbiError`s are turned into fatal errors or ICEs)."] fn handle_fn_abi_err (& self , err : FnAbiError < 'tcx > , span : Span , fn_abi_request : FnAbiRequest < 'tcx > ,) -> < Self :: FnAbiOfResult as MaybeResult < & 'tcx FnAbi < 'tcx , Ty < 'tcx > > > > :: Error ; }}}
mkitem!{mktrait!{# [doc = " Blanket extension trait for contexts that can compute `FnAbi`s."] pub trait FnAbiOf < 'tcx > : FnAbiOfHelpers < 'tcx > { # [doc = " Compute a `FnAbi` suitable for indirect calls, i.e. to `fn` pointers."] # [doc = ""] # [doc = " NB: this doesn't handle virtual calls - those should use `fn_abi_of_instance`"] # [doc = " instead, where the instance is an `InstanceKind::Virtual`."] # [inline] fn fn_abi_of_fn_ptr (& self , sig : ty :: PolyFnSig < 'tcx > , extra_args : & 'tcx ty :: List < Ty < 'tcx > > ,) -> Self :: FnAbiOfResult { let span = self . layout_tcx_at_span () ; let tcx = self . tcx () . at (span) ; MaybeResult :: from (tcx . fn_abi_of_fn_ptr (self . typing_env () . as_query_input ((sig , extra_args))) . map_err (| err | self . handle_fn_abi_err (* err , span , FnAbiRequest :: OfFnPtr { sig , extra_args }) ,) ,) } # [doc = " Compute a `FnAbi` suitable for declaring/defining an `fn` instance, and for"] # [doc = " direct calls to an `fn`."] # [doc = ""] # [doc = " NB: that includes virtual calls, which are represented by \"direct calls\""] # [doc = " to an `InstanceKind::Virtual` instance (of `<dyn Trait as Trait>::fn`)."] # [inline] # [tracing :: instrument (level = "debug" , skip (self))] fn fn_abi_of_instance (& self , instance : ty :: Instance < 'tcx > , extra_args : & 'tcx ty :: List < Ty < 'tcx > > ,) -> Self :: FnAbiOfResult { let span = self . layout_tcx_at_span () ; let tcx = self . tcx () . at (span) ; MaybeResult :: from (tcx . fn_abi_of_instance (self . typing_env () . as_query_input ((instance , extra_args))) . map_err (| err | { let span = if ! span . is_dummy () { span } else { tcx . def_span (instance . def_id ()) } ; self . handle_fn_abi_err (* err , span , FnAbiRequest :: OfInstance { instance , extra_args } ,) }) ,) } }}}
